<script setup lang="ts">
import '../styles/workspaces.css'
import StateNotice from '../components/StateNotice.vue'
import {computed,onMounted,onUnmounted,ref} from 'vue';import {useRoute} from 'vue-router';import {assistantApi,parseAgentContext,type AgentContext,type AgentMeta,type RunView} from '../assistant/api';import {clearHistory,readHistory,safeEvidenceHref,saveHistory,terminal} from '../assistant/state'
import ResearchContextBar from '../components/ResearchContextBar.vue'
const meta=ref<AgentMeta|null>(null), question=ref(''), run=ref<RunView|null>(null), history=ref<string[]>(readHistory()), memory=ref<{question:string;summary:string}[]>([]), error=ref(''), busy=ref(false), expanded=ref(false);let stopped=false, controller:AbortController|null=null
const route=useRoute();const parsedContext=computed(()=>parseAgentContext(route.query.context??(typeof route.query.plantId==='string'?JSON.stringify({plantId:Number(route.query.plantId),sampleIds:[]}):undefined)));const context=computed(()=>parsedContext.value.context),contextError=computed(()=>parsedContext.value.error)
const examples=['叶子像扇子的植物有哪些？','银杏和其他树木有什么不同？','为什么有些植物的种子含有油脂？']
onMounted(async()=>{const rawQuestion=route.query.question;if(typeof rawQuestion==='string')question.value=rawQuestion.slice(0,1500);try{meta.value=await assistantApi.meta()}catch(e){error.value=(e as Error).message}})
onUnmounted(()=>{stopped=true;controller?.abort()})
async function ask(text=question.value){const q=text.trim();if(!q||busy.value)return;if(contextError.value){error.value=contextError.value;return}error.value='';busy.value=true;run.value=null;question.value=q;history.value=saveHistory(q);stopped=false;controller=new AbortController();try{let r=await assistantApi.start(q,controller.signal,context.value??undefined);run.value=r;const start=Date.now();while(!stopped&&!terminal(r.status)&&Date.now()-start<90000){await new Promise(resolve=>setTimeout(resolve,500));if(stopped)break;r=await assistantApi.poll(r.id,controller.signal);run.value=r}if(!stopped&&!terminal(r.status))error.value='查询超过 90 秒，服务端仍可能继续运行。';if(!stopped&&terminal(r.status))memory.value=[{question:q,summary:r.answer?.summary||r.errorCode||r.status},...memory.value].slice(0,8)}catch(e){if((e as Error).name!=='AbortError'){const status=(e as {status?:number}).status;error.value=status===404&&context.value?'工作台上下文包含当前公开 Research Agent 不可访问的未发布样本或候选记录。请切回公开范围后再提交。':(e as Error).message}}finally{busy.value=false;controller=null}}
async function cancel(){if(!run.value)return;try{run.value=await assistantApi.cancel(run.value.id);stopped=true;controller?.abort()}catch(e){error.value=(e as Error).message}}
function clear(){if(busy.value)return;clearHistory();history.value=[];memory.value=[];run.value=null;question.value='';error.value=''}
</script>
<template><main class="assistant-page"><header class="assistant-intro"><p class="section-kicker">VIRIDEXA / FIELD NOTES</p><h1>问问植序</h1><h2 class="assistant-subtitle">从一个小小的好奇，开始认识植物。</h2><p>从公开植物目录、获准展示的来源记录与人工核验事实中检索。每条回答附带可核对的记录与来源。</p><p v-if="meta" class="assistant-mode">{{meta.modelConfigured?`模型已配置 · ${meta.model||'服务端模型'} · 联调状态未知`:'领域检索模式 · 尚未配置生成式模型'}} <span>每日 {{meta.limits.userDailyRequests}} 次 / 总额度 {{meta.limits.globalDailyRequests}}</span></p><p v-if="meta?.notice" class="assistant-notice">{{meta.notice}}</p><ResearchContextBar v-if="context" :context="context" title="来自 URL 的研究上下文"/><p v-if="context" class="assistant-notice">上下文会随问题提交；服务端负责验证可访问记录。</p><StateNotice v-if="contextError" tone="error" title="上下文不可用">{{contextError}}</StateNotice><StateNotice v-if="error" tone="error" title="请求未完成">{{error}}</StateNotice></header>
<section class="assistant-desk" aria-label="Field notes 与研究结果"><aside class="assistant-compose" aria-label="Field notes / 问题与历史"><label for="botanical-question">研究问题</label><textarea id="botanical-question" v-model="question" rows="4" maxlength="1500" placeholder="有什么植物，让你好奇？试试输入一个名字或一个问题。"></textarea><div class="assistant-examples"><span>研究问题示例</span><button v-for="example in examples" :key="example" class="history-item" :disabled="busy" @click="question=example">{{example}}</button></div><div class="assistant-actions"><small>答案仅基于实际检索到的公开记录。</small><button class="search-button" :disabled="busy||!question.trim()" @click="ask()">{{busy?'检索中…':'开始检索'}}</button><button v-if="busy" class="plain-button" :disabled="!run" @click="cancel">取消运行</button><button v-else-if="run" class="plain-button" @click="ask(run.question)">重试</button></div><div v-if="history.length" class="history"><div><b>最近问题</b><button class="plain-button" :disabled="busy" @click="clear">清除</button></div><button v-for="q in history" :key="q" class="history-item" @click="question=q">{{q}}</button></div></aside>
<div v-if="memory.length" class="assistant-memory" aria-label="本次打开期间的研究记录"><h2>本次研究记录</h2><article v-for="(item,index) in memory" :key="`${index}-${item.question}`"><b>{{item.question}}</b><p>{{item.summary}}</p></article></div><section v-if="run" class="assistant-result" aria-label="回答、检索时间线与证据"><div class="run-heading" aria-live="polite" aria-atomic="true"><span>运行 {{run.id}}</span><strong>{{run.status}}</strong></div><p>{{run.answer?.summary||run.errorCode||'正在检索公开资料…'}}</p><p v-if="run.mode==='SEARCH_FALLBACK'" class="assistant-notice">本次使用领域检索回退；没有生成式模型参与。</p><p v-if="run.usage.tokenUsageComplete" class="usage">模型调用 {{run.usage.modelCalls}} · 工具调用 {{run.usage.toolCalls}} · Token {{run.usage.inputTokens+run.usage.outputTokens}} · 估算费用 {{run.usage.estimatedCost??'—'}} {{run.usage.currency||''}}</p><p v-else-if="run.mode==='SEARCH_FALLBACK' && run.usage.modelCalls===0" class="usage">本次没有调用模型；无模型 Token 或费用。</p><p v-else class="usage">模型调用 {{run.usage.modelCalls}} · 工具调用 {{run.usage.toolCalls}} · Token/费用用量未知（服务端未提供完整用量）</p><details><summary>查看探索过程（{{run.trace.length}}）</summary><ol><li v-for="t in run.trace" :key="t.sequence"><b>{{t.tool}}</b> · {{t.status}} · {{t.elapsedMs}} ms · {{t.resultCount}} 条结果 <span>{{t.message}}</span><small v-if="t.recordIds.length">记录：{{t.recordIds.join(' · ')}}</small></li></ol></details><div v-if="run.answer?.claims.length" class="evidence-grid"><article v-for="item in run.answer.claims" :key="item.id" class="evidence-card"><small>{{item.category}} · {{item.knowledgeConfidence||item.verificationState}} / {{item.publicationState}}</small><h2>{{item.label}}</h2><details><summary>查看记录与来源字段</summary><p class="long-id">{{item.id}}</p><dl><template v-for="(value,key) in item.fields" :key="key"><dt>{{key}}</dt><dd>{{typeof value==='string'?value:JSON.stringify(value)}}</dd></template></dl></details><a v-if="safeEvidenceHref(item.href)" :href="safeEvidenceHref(item.href)!" target="_blank" rel="noopener">打开 API 记录 ↗</a><RouterLink v-if="item.graphNodeId" :to="{path:'/knowledge-graph',query:{nodeId:item.graphNodeId}}">在知识图谱中查看 →</RouterLink><details v-if="item.sources.length"><summary>来源（{{item.sources.length}}）</summary><pre>{{JSON.stringify(item.sources,null,2)}}</pre></details></article></div><p v-for="limitation in run.answer?.limitations||[]" :key="limitation" class="assistant-notice">{{limitation}}</p></section><p v-else class="assistant-empty">检索结果与来源将在此显示。</p></section></main></template>
